var generateString = function (str1, str2) {
    const n = str1.length;
    const m = str2.length;
    const len = n + m - 1;
    const dp = new Array(len).fill('a');
    const fixed = new Array(len).fill(0);

    for (let i = 0; i < n; i++) {
        if (str1[i] === 'T') {
            for (let j = i; j < i + m; j++) {
                if (fixed[j] === 1 && dp[j] !== str2[j - i]) {
                    return '';
                }

                dp[j] = str2[j - i];
                fixed[j] = 1;
            }
        }
    }

    for (let i = 0; i < n; i++) {
        if (str1[i] === 'F') {
            let flag = false;
            let idx = -1;

            for (let j = i + m - 1; j >= i; j--) {
                if (str2[j - i] !== dp[j]) {
                    flag = true;
                }
                if (idx === -1 && fixed[j] === 0) {
                    idx = j;
                }
            }

            if (flag) continue;
            if (idx === -1) return '';

            dp[idx] = 'b';
        }
    }

    return dp.join('');
};

